import test from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { readEmail, threadKeys } from "../server/email-read";
import { baseSubject, stripReply } from "../server/email-quotes";
import { sanitizeEmailHtml } from "../server/email-html";

/**
 * The acceptance corpus (phase 12, E2; docs/OMNICHANNEL_STEP2.md): 50 inbound emails, each read
 * as expected. Generated by `scripts/email-corpus.py`: forwarded chains, Outlook and Gmail quoting,
 * mobile signatures, auto-replies, bounces, non-Latin character sets, attachments, hostile HTML.
 */
type Expected = {
  file: string;
  kind: "message" | "auto_reply" | "bounce";
  from: string;
  subject: string;
  text?: string;
  stripped?: boolean;
  forwarded?: boolean;
  verified?: boolean;
  reason?: string;
  bounce?: { hard: boolean; recipients: string[] };
  attachments?: string[];
  inlineImages?: number;
  remoteImages?: number;
  htmlMustContain?: string[];
  htmlMustNotContain?: string[];
};
const dir = new URL("./fixtures/email/", import.meta.url);

test("the 50-email corpus: each email read as expected (kind, sender, subject, the new text, threading, attachments, safety)", async () => {
  const { trustedAuthServ, emails } = JSON.parse(await readFile(new URL("expected.json", dir), "utf8")) as { trustedAuthServ: string[]; emails: Expected[] };
  assert.equal(emails.length, 50);
  const failures: string[] = [];
  const check = (file: string, what: string, actual: unknown, expected: unknown) => {
    try {
      assert.deepEqual(actual, expected);
    } catch {
      failures.push(`${file}: ${what}\n    expected ${JSON.stringify(expected)}\n    got      ${JSON.stringify(actual)}`);
    }
  };
  for (const e of emails) {
    const m = await readEmail(new Uint8Array(await readFile(new URL(e.file, dir))), { trustedAuthServ });
    const n = Number(e.file.slice(0, 2));
    check(e.file, "kind", m.kind, e.kind);
    check(e.file, "from", m.from?.address, e.from);
    check(e.file, "subject", m.subject, e.subject);
    check(e.file, "message id", m.messageId, `msg-${String(n).padStart(2, "0")}@mail.example.net`);
    if (e.text !== undefined) check(e.file, "text", m.text, e.text);
    if (e.stripped !== undefined) check(e.file, "stripped", m.stripped, e.stripped);
    check(e.file, "forwarded", m.forwarded, e.forwarded ?? false);
    check(e.file, "verified", m.verified, e.verified ?? false);
    if (e.reason) check(e.file, "reason", m.reason, e.reason);
    if (e.bounce) check(e.file, "bounce", { hard: m.bounce?.hard, recipients: m.bounce?.recipients.map((r) => r.address) }, e.bounce);
    check(e.file, "attachments", m.attachments.map((a) => a.filename), e.attachments ?? []);
    if (e.inlineImages !== undefined) check(e.file, "inline images", (m.html?.match(/src="data:image\//g) ?? []).length, e.inlineImages);
    if (e.remoteImages !== undefined) check(e.file, "remote images", m.remoteImages, e.remoteImages);
    for (const s of e.htmlMustContain ?? []) check(e.file, `html has ${s}`, m.html?.includes(s), true);
    for (const s of e.htmlMustNotContain ?? []) check(e.file, `html has no ${s}`, m.html?.toLowerCase().includes(s.toLowerCase()), false);
    // Replies thread by what they answer; the full text is always kept.
    if (/^(re|aw|rv|sv)\s*:/i.test(e.subject)) check(e.file, "threads", (await threadKeys(m)).threadKeys.length > 0, true);
    check(e.file, "full text kept", m.fullText.length >= m.text.length, true);
  }
  assert.equal(failures.length, 0, `\n${failures.join("\n")}`);
});

test("broken mail is read, not thrown: empty, headers only, a missing boundary, no sender", async () => {
  const read = (raw: string) => readEmail(new TextEncoder().encode(raw), { trustedAuthServ: [] });
  const empty = await read("");
  assert.deepEqual([empty.kind, empty.from, empty.text], ["message", null, ""]);
  const headersOnly = await read("From: a@b.example\r\nSubject: Hi\r\nMessage-ID: <x@b>\r\n");
  assert.deepEqual([headersOnly.from?.address, headersOnly.subject, headersOnly.text, headersOnly.messageId], ["a@b.example", "Hi", "", "x@b"]);
  const broken = await read('From: a@b.example\r\nSubject: Broken\r\nContent-Type: multipart/mixed; boundary="nope"\r\n\r\nno boundary\r\n--other\r\n\r\nhi');
  assert.deepEqual([broken.subject, broken.attachments.length], ["Broken", 0]);
  // No sender: email-in fails it ("It has no sender.") rather than open a conversation.
  assert.equal((await read("Subject: Anonymous\r\n\r\nhello")).from, null);
});

test("quotes, subjects and HTML: the edges", () => {
  // Nothing but a quote: the whole is kept, rather than nothing.
  assert.deepEqual(stripReply("> only a quote\n> here"), { text: "> only a quote\n> here", stripped: false, forwarded: false });
  // A "From:" line in the customer's own words isn't Outlook's header.
  assert.equal(stripReply("From: my point of view, it's broken.\nIt fails every time.").text, "From: my point of view, it's broken.\nIt fails every time.");
  assert.equal(baseSubject("RE: Fwd: AW: [Ticket #12] Late order"), "late order");
  assert.equal(baseSubject("回复：退款"), "退款");
  const { html } = sanitizeEmailHtml('<a href="https://x.example" onclick="x()">x</a><img src="cid:a"><img src="data:image/svg+xml;base64,PHN2Zz4=">', new Map([["a", "data:image/png;base64,AAAA"]]));
  assert.equal(html, '<a href="https://x.example" rel="noopener noreferrer" target="_blank">x</a><img src="data:image/png;base64,AAAA"><img>');
});
